from pathlib import Path
from PIL import Image
import hashlib,json
p=Path(__file__).resolve().parent;r=p.parents[1];out=p/'start-bridge-v17';out.mkdir(exist_ok=True)
walking=p/'master-head-review-v16/bare-000.png';standing=r/'character/james-carry-headcaps-v1/frames/004.png';original=r/'character/james-west-master-carry-v1/local-original.png'
crop=[64,96,208,240];rect=[88,104,166,228]
for i in (1,2):
 name=f'start-{i:03}';refs=[];files=[walking,standing,original,Path(__file__),p/'package_start_bridge_v17.py',p/'package_start_bridge_v15.py']
 for f,label in [(walking,'target'),(standing,'standing-reference'),(original,'body-master')]:
  target=out/f'{name}-{label}.png';Image.open(f).convert('RGBA').crop(crop).resize((576,576),Image.Resampling.LANCZOS).save(target);refs.append(target);files.append(target)
 pose=('A halfway body-yaw/weight-settle pose: more side-facing and narrower than image2 standing, but still slightly more open than image1 fully side-facing walk. Knees and shins project toward each other with natural depth; far kneepad begins to be occluded by the near leg. Do NOT give two front-facing separated full kneepads like image2.' if i==1 else 'An almost fully side-facing walk-ready pose, only a small final settle away from image1. Near thigh/kneepad/shin/boot keep image1 side profile and scale. Far leg is partly hidden in depth behind near leg, with only its genuine knee/boot exposure. Do NOT return to image2 two separated front-facing knees or wide standing stance.')
 prompt=f'''Edit image1 ONLY: James West carrying start transition interior{i}. Image1 is the actual walk-ready endpoint; image2 is the actual wider standing-carry endpoint; image3 is original selected standing clothing/material authority. Same144x144 native body crop enlarged4x, full256 canvas, fixed pivot128224, standing ruler148. Create ONE intentional stance in-between, not a sheet, by changing image1 body/legs slightly toward image2. {pose} This is a small in-place yaw/weight shift, NOT another step: boots stay close to existing foot contacts on native groundy224/cropy128; no kicked-forward foot, crossing shin anatomy, kneeling, squat, height bob or sliding whole body. Maintain image1 anatomical knee/boot design and soft neutral matte grey/yellow detailed sprite material; do not enlarge legs, pads, cuffs, case or shoulder. Keep original selected master head/collar at identical framing and preserve all pixels outside the needed body stance. Keep one modest rigid graphite case at same low waist height, four small dull silver corner latches and coherent two-hand grip interpolating gently between endpoints. No case lift/drop, black occlusion holes, new wrench or near-side metal loop, duplicate/relocated meter, silver gloss or purple cast. Anatomical-left meter retains original high belt attachment and natural glove occlusion; anatomical-right wrench remains far-side occluded. Do not copy image3 lowered arms. Do not fit body to a new bounding-box height. Return the whole same square image1 crop with transparent background and ONLY the coherent small stance/grip transition.'''
 pf=out/f'{name}-prompt.txt';pf.write_text(prompt+'\n',encoding='utf-8');files.append(pf)
 (out/f'{name}-inputs.json').write_text(json.dumps({'preCallSha256':{f.relative_to(r).as_posix():hashlib.sha256(f.read_bytes()).hexdigest() for f in set(files)},'crop':crop,'admissionRegion':rect,'baseFile':walking.relative_to(r).as_posix(),'references':[f.relative_to(r).as_posix() for f in refs],'scope':'Walking-endpoint-authored yaw/stance bridge trial. Preserve exact master head at native coordinates; no per-pose fitting.'},indent=2)+'\n')
